   227    FT_LOCAL_DEF( void )
   228    tt_face_free_cpal( TT_Face  face )
   229    {
   230      FT_Stream  stream = face->root.stream;
   231      FT_Memory  memory = face->root.memory;
   232
   233      Cpal*  cpal = (Cpal*)face->cpal;
   234
   235
   236      if ( cpal )
   237      {
   238        FT_FRAME_RELEASE( cpal->table );
   239        FT_FREE( cpal );
   240      }
   241    }
