   244    FT_LOCAL_DEF( FT_Error )
   245    tt_face_palette_set( TT_Face  face,
   246                         FT_UInt  palette_index )
   247    {
   248      Cpal*  cpal = (Cpal*)face->cpal;
   249
   250      FT_Byte*   offset;
   251      FT_Byte*   p;
   252
   253      FT_Color*  q;
   254      FT_Color*  limit;
   255
   256
   257      if ( palette_index >= face->palette_data.num_palettes )
   258        return FT_THROW( Invalid_Argument );
   259
   260      offset = cpal->color_indices + 2 * palette_index;
   261      p      = cpal->colors + COLOR_SIZE * FT_PEEK_USHORT( offset );
   262
   263      q     = face->palette;
   264      limit = q + face->palette_data.num_palette_entries;
   265
   266      while ( q < limit )
   267      {
   268        q->blue  = FT_NEXT_BYTE( p );
   269        q->green = FT_NEXT_BYTE( p );
   270        q->red   = FT_NEXT_BYTE( p );
   271        q->alpha = FT_NEXT_BYTE( p );
   272
   273        q++;
   274      }
